#!/usr/bin/env python3
"""Differential fuzzer: submission vs naive reference."""
import json, os, random, subprocess, sys, tempfile, shutil

SUB = "/workspace/submission/main.py"
REF = "/workspace/tmp/ref.py"

def run_cmd(args, inp=b""):
    p = subprocess.run([sys.executable, "-I"] + args, input=inp,
                       stdout=subprocess.PIPE, stderr=subprocess.PIPE, timeout=120)
    return p.returncode, p.stdout, p.stderr

def gen_config(rng, small=True):
    W = rng.randint(1, 6 if small else 32)
    nrules = rng.randint(0, 6 if small else 40)
    rules = []
    used = set()
    for _ in range(nrules):
        while True:
            rid = rng.randint(0, 40)
            if rid not in used:
                used.add(rid); break
        k = rng.randint(1, min(4 if small else 8, 32))
        ranges = []
        for _ in range(k):
            lo = rng.randint(-30, 30); hi = lo + rng.randint(0, 12)
            ranges.append([lo, hi])
        rules.append({"id": rid, "class": rng.randint(0, 4),
                      "priority": rng.randint(-5, 5), "ranges": ranges})
    def tree(depth):
        if depth >= 3 or rng.random() < 0.35:
            return {"class": rng.randint(0, 4)}
        return {"feature": rng.randint(0, W-1), "threshold": rng.randint(-30, 30),
                "le": tree(depth+1), "gt": tree(depth+1)}
    return {"version": 1, "idle_timeout": rng.randint(0, 12), "packet_limit": rng.randint(1, 8),
            "prefix_width": W, "rules": rules, "fallback": tree(0)}

def gen_requests(rng, cfg, nops=60, maxflows=4):
    W = cfg["prefix_width"]
    ops = []
    t = 0
    open_flows = set()
    closed = set()
    all_ids = list(range(maxflows))
    for _ in range(nops):
        r = rng.random()
        t += rng.choice([0, 0, 1, 1, 2, 3, 5, 11])
        if r < 0.18:
            cand = [f for f in all_ids if f not in open_flows]
            if not cand: continue
            f = rng.choice(cand)
            ops.append({"op": "open", "flow": f, "time": t})
            open_flows.add(f)
        elif r < 0.55:
            if not open_flows: continue
            pk = []
            for _ in range(rng.randint(0, 5)):
                if not open_flows: break
                t += rng.choice([0, 0, 0, 1, 2, 4, 13])
                f = rng.choice(sorted(open_flows))
                pk.append({"flow": f, "time": t, "source": rng.randint(0, 1),
                           "length": rng.choice([rng.randint(1, 60), rng.randint(1, 2048)])})
            ops.append({"op": "chunk", "packets": pk})
        elif r < 0.68:
            ops.append({"op": "tick", "time": t})
        elif r < 0.85:
            if not open_flows: continue
            f = rng.choice(sorted(open_flows))
            ops.append({"op": "close", "flow": f, "time": t})
            open_flows.discard(f)
            closed.add(f)
        elif r < 0.93:
            ops.append({"op": "checkpoint"})
        else:
            ops.append({"op": "tick", "time": t})
    return ops

def lines_of(ops):
    return "".join(json.dumps(o) + "\n" for o in ops)

def compare(cfg, ops, verbose=False):
    with tempfile.TemporaryDirectory() as d:
        prog_path = os.path.join(d, "program.json")
        rc, out, err = run_cmd([SUB, "compile"], json.dumps(cfg).encode())
        if rc != 0:
            return ["compile rc=%d %r" % (rc, err[:400])]
        prog = json.loads(out)
        if not isinstance(prog, dict) or "error" in prog:
            return ["bad program %r" % (out[:200],)]
        open(prog_path, "w").write(json.dumps(prog))
        data = lines_of(ops).encode()
        rc1, out1, err1 = run_cmd([SUB, "stream", prog_path], data)
        rc2, out2, err2 = run_cmd([REF, prog_path], data)
        if rc1 != rc2:
            return ["rc mismatch %d %d\n%r\n%r" % (rc1, rc2, err1[:400], err2[:400])]
        a = out1.decode().splitlines()
        b = out2.decode().splitlines()
        if a != b:
            res = []
            for i, (x, y) in enumerate(zip(a, b)):
                if x != y:
                    res.append("line %d req=%s\n  sub=%s\n  ref=%s" % (i, json.dumps(ops[i]) if i < len(ops) else "?", x, y))
                    if len(res) > 3: break
            if len(a) != len(b):
                res.append("len mismatch %d %d" % (len(a), len(b)))
            return res
    return []

def main():
    seed0 = int(sys.argv[1]) if len(sys.argv) > 1 else 0
    n = int(sys.argv[2]) if len(sys.argv) > 2 else 200
    bad = 0
    for it in range(n):
        rng = random.Random(seed0 + it)
        cfg = gen_config(rng)
        ops = gen_requests(rng, cfg)
        res = compare(cfg, ops)
        if res:
            bad += 1
            print("=== FAIL seed", seed0 + it)
            print("CONFIG", json.dumps(cfg))
            print("REQS", lines_of(ops))
            for r in res: print(r)
            if bad >= 3: break
    print("done, failures:", bad)

main()
PYEOF
